const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const config = window.GOA_CONFIG || {};
const live = !!(config.supabaseUrl && config.supabaseKey && config.tripId);
const key = 'goa-afterglow-personal-v1';
const initial = () => ({trip:{title:'Our Goa escape',departure:'',start:'',end:'',budget:'',notes:''},entries:[],members:[],votes:[],files:[]});
let state;try{state = live ? initial() : JSON.parse(localStorage.getItem(key)) || initial()}catch{state=initial()}
let session = null, member = null, currentPage = 'overview', timer, refreshTimer, syncTimer;
const tabs = [['overview','⌂','Overview'],['itinerary','◷','Itinerary'],['discussions','☏','Discussions'],['polls','▥','Polls & decisions'],['expenses','₹','Expenses'],['checklist','☑','Checklist'],['links','↗','Links & bookings'],['crew','♧','The crew'],['settings','⚙','Trip settings']];
const entries = kind => state.entries.filter(e => e.kind === kind).sort((a,b) => a.created_at.localeCompare(b.created_at));
const isAdmin = () => !live || member?.role === 'admin';
const canWrite = () => !live || !!member;
const mine = e => !live || e.author_id === session?.user?.id;
const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const date = d => d ? new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'}) : 'Not set';
const name = () => member?.display_name || session?.user?.display_name || 'You';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function persist(){if(!live)localStorage.setItem(key,JSON.stringify(state))}
async function api(action,data={}){
 const r=await fetch(config.supabaseUrl+'/functions/v1/goa-trip-api',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,data})});
 const value=await r.json().catch(()=>({error:'The server could not complete the request.'}));
 if(!r.ok){if(r.status===401&&session){saveSession(null);member=null;state=initial();render()}throw Error(value.error||'Request failed');}return value;
}
function saveSession(value){session=value;if(value)localStorage.setItem('goa-custom-session-v3',JSON.stringify(value));else localStorage.removeItem('goa-custom-session-v3');sessionStorage.removeItem('goa-custom-session-v2')}
async function sync(){if(!live||!session)return;state=await api('get');member=state.members.find(m=>m.user_id===session.user.id)||null;render()}
async function addEntry(kind,data){if(!canWrite())return openAccount();if(live){await api('add',{kind,data});await sync()}else{state.entries.push({id:crypto.randomUUID(),kind,data,author_id:'local',created_at:new Date().toISOString()});persist();render()}toast('Added to the trip.')}
async function updateEntry(e,data){if(live){await api('update',{id:e.id,data});await sync()}else{e.data=data;persist();render()}}
async function removeEntry(id){const e=state.entries.find(x=>x.id===id);if(!e)return;openModal('Remove this item?',`<p class="modal-note">Remove “${esc(e.data.title||e.data.text||'this item')}” from the trip?</p><div class="form-actions"><button class="button outline" data-close>Keep it</button><button class="button danger" id="confirm-remove">Remove item</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{if(live){await api('delete',{id});await sync()}else{state.entries=state.entries.filter(e=>e.id!==id);state.votes=state.votes.filter(v=>v.entry_id!==id);persist();render()}closeModal();toast('Item removed.')})}

function openModal(title,html){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Close dialog">×</button></div>${html}`;if(!$('#modal').open)$('#modal').showModal();$('#modal-content').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){$('#modal').querySelectorAll('input[type=password]').forEach(i=>i.value='');$('#modal').close()}
async function run(fn){const buttons=[...$('#modal').querySelectorAll('button[type="submit"],#confirm-remove')];buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}
function form(title,fields,onSubmit,note=''){openModal(title,`${note?`<p class="modal-note">${esc(note)}</p>`:''}<form id="edit-form">${fields}<div class="form-actions"><button type="button" class="button outline" data-close>Cancel</button><button class="button" type="submit">Save ${title.startsWith('Create poll')?'poll':'details'} ↗</button></div></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));run(async()=>{await onSubmit(values);closeModal()})}}
const field=(label,key,type='text',value='',required=false)=>`<label for="field-${key}">${esc(label)}</label><input id="field-${key}" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="999999999" step="0.01"':''} maxlength="${type==='text'?'300':'1000'}">`;
const area=(label,key,value='')=>`<label for="field-${key}">${esc(label)}</label><textarea id="field-${key}" name="${key}" maxlength="10000">${esc(value)}</textarea>`;
function addForm(kind){if(!canWrite())return openAccount();const forms={
 itinerary:['Add a plan',field('What’s the plan?','title','text','',true)+`<div class="field-pair">${field('Date','date','date')}${field('Time','time','time')}</div>`+field('Location','location')+area('Notes','notes'),async v=>{await addEntry(kind,v)}],
 expense:['Add an expense',field('What was it for?','title','text','',true)+field('Amount (INR)','amount','number','',true)+field('Paid by','payer','text',name(),true)+area('Notes','notes'),async v=>{if(Number(v.amount)<=0)throw Error('Enter an amount greater than zero.');await addEntry(kind,{...v,amount:Number(v.amount)})}],
 checklist:['Add a checklist item',field('What needs doing or packing?','title','text','',true)+field('Who’s taking care of it?','assignee')+`<label for="field-category">Category</label><select id="field-category" name="category"><option>To do</option><option>Packing</option><option>Before departure</option></select>`,async v=>{await addEntry(kind,{...v,done:false})}],
 link:['Add a useful link',field('Title','title','text','',true)+field('Website or Google Drive link','url','url','',true)+`<label for="field-category">Category</label><select id="field-category" name="category"><option>Google Drive</option><option>Stay</option><option>Travel</option><option>Places & ideas</option><option>Other</option></select>`+area('Notes','notes'),async v=>{const u=new URL(v.url);if(!['https:','http:'].includes(u.protocol))throw Error('Use an http or https link.');await addEntry(kind,v)}],
 poll:['Create poll',field('What should we decide?','title','text','',true)+area('Options (one per line, at least two)','options'),async v=>{const options=[...new Set(v.options.split('\n').map(s=>s.trim()).filter(Boolean))];if(options.length<2||options.length>10)throw Error('Add between 2 and 10 different options.');await addEntry(kind,{title:v.title,options})}]
 };const f=forms[kind];form(...f)}
function renderNav(){const active=tabs.find(t=>t[0]===currentPage)||tabs[0];$('#nav').innerHTML=tabs.map((t,i)=>`${i===8?'<div class="nav-separator"></div>':''}<a class="nav-link ${t[0]===active[0]?'active':''}" href="#${t[0]}" ${t[0]===active[0]?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${t[1]}</span>${t[2]}${t[0]==='crew'&&state.members.length?`<span class="nav-count">${state.members.length}</span>`:''}</a>`).join('');$('#page-label').textContent=active[2]}
const intro=(eyebrow,title,subtitle,action='')=>`<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="intro-note">${subtitle}</p></div>${action}</div>`;
const empty=(symbol,title,body,button='',action='')=>`<div class="empty"><div class="empty-symbol" aria-hidden="true">${symbol}</div><h3>${title}</h3><p>${body}</p>${button?`<button class="button small light" data-action="${action}">${button} ↗</button>`:''}</div>`;
function deleteButton(e){return (isAdmin()||mine(e))?`<button class="delete-button" data-delete="${e.id}" aria-label="Remove ${esc(e.data.title||'item')}">×</button>`:''}
const palms=`<svg class="palms" viewBox="0 0 300 380" fill="none" aria-hidden="true"><path d="M210 390Q165 245 198 80" stroke="#245f50" stroke-width="14"/><path d="M195 85Q134 14 61 61Q131 47 182 92Q93 68 44 130Q116 100 187 100Q121 112 99 195Q144 128 192 105Q178 163 196 209Q214 148 201 98Q240 149 289 163Q274 110 207 90Q252 61 300 92Q284 31 205 77Q223 20 192 4Q178 39 195 85Z" fill="#245f50"/><path d="M277 389Q254 287 273 206" stroke="#3a7660" stroke-width="9"/><path d="M272 210Q224 167 186 192Q228 185 266 219Q218 207 185 244Q237 226 268 223Q238 249 241 294Q264 259 274 226Q293 270 321 270L305 219Q309 185 274 210Z" fill="#3a7660"/></svg>`;
function overview(){const plans=entries('itinerary');const total=entries('expense').reduce((s,e)=>s+Number(e.data.amount),0);const days=state.trip.start?Math.ceil((new Date(state.trip.start+'T00:00:00')-new Date(new Date().toDateString()))/86400000):null;return intro('THE PLAN IS TO MAKE MEMORIES','A little closer to <span class="soft">Goa.</span>','Big ideas, small details, and everyone in one place.',`<span class="date-chip">◷ &nbsp; ${state.trip.start?date(state.trip.start)+' — '+date(state.trip.end):'Dates are still a blank canvas'}</span>`)+`<section class="hero"><div class="hero-art"><div class="sun"></div><div class="island"></div><div class="wave one"></div><div class="wave two"></div><div class="wave three"></div>${palms}</div><span class="hero-number">01</span><div class="hero-copy"><div class="eyebrow">✦ &nbsp; A LITTLE SUN. A LOT OF STORIES.</div><h2>Good company.<br>Great <em>getaway.</em></h2><p>A space for our plans, our people, and the days we’ll talk about long after Goa.</p><button class="button" data-action="plan">Let’s make a plan <span>↗</span></button></div><div class="hero-caption">MEET ME WHERE THE SEA IS</div></section><div class="stat-grid"><div class="stat"><span class="stat-icon">☀</span><div><div class="stat-label">The countdown</div><div class="stat-value">${days===null?'—':days>0?days:days===0?'Today':'Goa time'}<small>${days>0?'days to go':days===null?'set your dates':''}</small></div></div></div><div class="stat"><span class="stat-icon">♧</span><div><div class="stat-label">Our people</div><div class="stat-value">${state.members.length||'—'}<small>${state.members.length?'in the crew':'invite the crew'}</small></div></div></div><div class="stat"><span class="stat-icon">₹</span><div><div class="stat-label">Trip budget</div><div class="stat-value">${state.trip.budget?money(state.trip.budget):'—'}<small>${state.trip.budget?'total target':'to be decided'}</small></div></div></div><div class="stat"><span class="stat-icon">◷</span><div><div class="stat-label">Plans on the board</div><div class="stat-value">${plans.length}<small>and counting</small></div></div></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>A plan in the making</h2><a class="text-link" href="#itinerary">Full itinerary ↗</a></div>${plans.length?plans.slice(0,3).map(planRow).join(''):empty('◷','Every good story starts somewhere.','Add your first stop, a beach day, or just a slow morning.','Add the first plan','add-itinerary')}</section><section class="panel"><div class="panel-head"><h2>Let’s get everyone here</h2><span class="eyebrow" style="font-size:8px">THE CREW</span></div>${state.members.length?state.members.slice(0,3).map(m=>`<div class="row"><span class="avatar">${esc(m.display_name?.[0]||'G')}</span><div class="row-main"><h3>${esc(m.display_name)}</h3><p>${esc(m.role)}</p></div></div>`).join(''):empty('♧','Better with your people.','Invite your travel crew. One shared place, a lot less back-and-forth.','Invite participants','invite')}<div class="callout"><span style="font-size:23px">✳</span><p><strong>Make room for the unplanned.</strong>The best moments rarely need an itinerary.</p></div></section></div><div class="section-grid"><a class="feature-card" href="#polls"><span class="arrow">↗</span><div class="feature-icon">▥</div><h3>Decide it together</h3><p>Beach or backwaters? Put it to a vote.</p></a><a class="feature-card" href="#expenses"><span class="arrow">↗</span><div class="feature-icon">₹</div><h3>Keep the money simple</h3><p>${total?money(total)+' logged so far.':'Shared costs, without the awkward maths.'}</p></a><a class="feature-card" href="#links"><span class="arrow">↗</span><div class="feature-icon">↗</div><h3>Everything, in one place</h3><p>Bookings, Drive folders, and saved ideas.</p></a></div>`}
function planRow(e){return `<div class="row"><span class="time-stamp">${esc(e.data.time||'TBD')}</span><div class="row-main"><h3>${esc(e.data.title)}</h3><p>${date(e.data.date)}${e.data.location?' · '+esc(e.data.location):''}${e.data.notes?'\n'+esc(e.data.notes):''}</p></div>${deleteButton(e)}</div>`}
function itinerary(){const list=entries('itinerary').sort((a,b)=>(a.data.date+' '+a.data.time).localeCompare(b.data.date+' '+b.data.time));return intro('THE DAYS AHEAD','Leave a little room for magic.','Build each day together. Nothing is fixed until you decide.',`<button class="button" data-action="add-itinerary">＋ Add a plan</button>`)+`<section class="panel full-panel">${list.length?list.map(planRow).join(''):empty('◷','No plans. Endless possibilities.','Start with your travel day or a place everyone wants to see.','Add a plan','add-itinerary')}</section>`}
function discussions(){const list=entries('message');return intro('THE GROUP CHAT, WITH A VIEW','Talk trip to me.','Ideas, questions, and those “what if we…” moments.')+`<section class="panel"><div class="chat-feed">${list.length?list.map(e=>`<article class="message ${mine(e)?'mine':''}"><div class="author">${esc(e.data.author||'Crew member')}</div><p>${esc(e.data.text)}</p><time>${new Date(e.created_at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time>${deleteButton(e)}</article>`).join(''):empty('☏','The conversation starts with you.','Drop an idea or ask the crew a question.')}</div><form id="chat-form" class="chat-form"><input name="text" aria-label="Your message" placeholder="What’s on your Goa wishlist?" maxlength="4000" required><button class="button" type="submit">Send ↗</button></form><p class="note">${live?'Messages refresh every 15 seconds.':'Personal preview: messages are saved in this browser only.'}</p></section>`}
function polls(){const list=entries('poll');return intro('FEWER MAYBES, MORE MEMORIES','Good ideas. Group decisions.','One vote per person on each poll. Change your mind anytime.',`<button class="button" data-action="add-poll">＋ Create a poll</button>`)+`${list.length?list.map(e=>{const vs=state.votes.filter(v=>v.entry_id===e.id);const own=vs.find(v=>v.user_id===(session?.user?.id||'local'));return `<section class="panel poll-card"><div class="panel-head"><h2>${esc(e.data.title)}</h2>${deleteButton(e)}</div>${e.data.options.map((o,i)=>{const n=vs.filter(v=>v.option_index===i).length;return `<button class="poll-option ${own?.option_index===i?'selected':''}" data-vote="${e.id}" data-option="${i}" aria-pressed="${own?.option_index===i}"><span class="poll-fill" style="width:${vs.length?n/vs.length*100:0}%"></span><span>${esc(o)} ${own?.option_index===i?'✓':''}</span><span>${n} vote${n!==1?'s':''}</span></button>`}).join('')}<p class="note">${vs.length} crew member${vs.length!==1?'s':''} voted</p></section>`}).join(''):`<section class="panel">${empty('▥','Decisions are better together.','Create a poll for dates, stays, activities, or whatever the group needs to decide.','Create a poll','add-poll')}</section>`}`}
function expenses(){const list=entries('expense'),total=list.reduce((s,e)=>s+Number(e.data.amount),0);const paid={};list.forEach(e=>paid[e.data.payer]=(paid[e.data.payer]||0)+Number(e.data.amount));return intro('LESS MATHS. MORE MOMENTS.','Keep tabs. Keep it easy.','Log shared spending and see who paid for what.',`<button class="button" data-action="add-expense">＋ Add expense</button>`)+`<div class="two-col"><section class="panel"><div class="eyebrow">TOTAL LOGGED</div><div class="summary-total">${money(total)}</div><p class="muted">${state.trip.budget?'Trip target: '+money(state.trip.budget):'Set a total trip budget in settings.'}</p></section><section class="panel"><div class="eyebrow">PAID BY</div>${Object.keys(paid).length?Object.entries(paid).map(([p,a])=>`<div class="row"><span class="row-main">${esc(p)}</span><strong>${money(a)}</strong></div>`).join(''):'<p class="intro-note">Your shared spending will appear here.</p>'}</section></div><section class="panel">${list.length?list.map(e=>`<div class="row"><span class="stat-icon">₹</span><div class="row-main"><h3>${esc(e.data.title)}</h3><p>Paid by ${esc(e.data.payer)}${e.data.notes?' · '+esc(e.data.notes):''}</p></div><strong>${money(e.data.amount)}</strong>${deleteButton(e)}</div>`).join(''):empty('₹','A clean slate.','Add costs as they happen: travel, stays, food, and everything in between.','Log an expense','add-expense')}</section><p class="note">A shared expense log. It does not collect payments or calculate individual settlements.</p>`}
function checklist(){const list=entries('checklist');return intro('THE LITTLE THINGS, COVERED','Ready, set, Goa.','From tickets to sunscreen. Give every detail a home.',`<button class="button" data-action="add-checklist">＋ Add an item</button>`)+`<section class="panel">${list.length?list.map(e=>`<div class="row"><input class="check" type="checkbox" aria-label="Complete ${esc(e.data.title)}" data-check="${e.id}" ${e.data.done?'checked':''}><div class="row-main"><h3 class="${e.data.done?'done':''}">${esc(e.data.title)}</h3><p>${esc(e.data.category)}${e.data.assignee?' · '+esc(e.data.assignee):''}</p></div>${deleteButton(e)}</div>`).join(''):empty('☑','Nothing forgotten. Nobody guessing.','Add shared to-dos, packing essentials, and pre-trip reminders.','Add an item','add-checklist')}</section>`}
function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function storagePanel(){const files=state.files||[];return `<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>The trip file cabinet</h2><div class="section-actions">${isAdmin()?'<button class="button small outline" data-action="prepare-storage">Prepare folders</button>':''}<button class="button small" data-action="upload">↑ Upload a file</button></div></div><p class="muted">Travel · Stay · Itinerary · Expenses · Shared documents · Photos and videos</p>${files.length?files.map(f=>`<div class="row"><span class="stat-icon">↗</span><div class="row-main"><h3>${esc(f.name)}</h3><p>${esc(storageCategories.find(([k])=>k===f.category)?.[1]||f.category)} · ${(f.size_bytes/1024/1024).toFixed(2)} MB</p></div><button class="button small outline" data-download="${f.id}">↓ Download</button>${isAdmin()||f.uploaded_by===session?.user?.id?`<button class="delete-button" data-remove-file="${f.id}" aria-label="Remove ${esc(f.name)}">×</button>`:''}</div>`).join(''):empty('↗','A place for every little detail.','Upload tickets, confirmations, receipts, plans, and memories. Each file goes into its matching Google Drive folder.','Upload a file','upload')}</section>`}
function links(){const list=entries('link');return intro('SAVE IT HERE. FIND IT LATER.','All the details. One happy place.','Drive folders, bookings, and that place someone sent once.',`<button class="button" data-action="add-link">＋ Save a link</button>`)+`<section class="panel">${list.length?list.map(e=>`<div class="row"><span class="stat-icon">↗</span><div class="row-main"><h3><a href="${safeUrl(e.data.url)}" target="_blank" rel="noopener noreferrer">${esc(e.data.title)} ↗</a></h3><p>${esc(e.data.category)}${e.data.notes?' · '+esc(e.data.notes):''}</p></div>${deleteButton(e)}</div>`).join(''):empty('↗','The end of “where’s that link?”','Save existing Google Drive folders and booking links. Drive access stays managed in Google Drive.','Save your first link','add-link')}</section><div class="callout"><span style="font-size:24px">♧</span><p><strong>Shared with the crew, not the internet.</strong>Keep sensitive tickets and identity documents in a restricted Drive folder; share its link here.</p></div>${storagePanel()}`}
function crew(){return intro('YOUR FAVOURITE TRAVEL COMPANIONS','The people make the trip.','A private space for the people you invite.',`<button class="button" data-action="invite">↗ Invite participants</button>`)+`<section class="panel">${state.members.length?`<div class="people-grid">${state.members.map(m=>`<div class="person-card"><span class="avatar">${esc(m.display_name?.[0]||'G')}</span><div>${esc(m.display_name)}<small>${esc(m.role)}${m.user_id===session?.user?.id?' · you':''}</small></div>${isAdmin()&&m.role!=='admin'?`<button class="delete-button" data-remove-member="${m.user_id}" aria-label="Remove member">×</button>`:''}</div>`).join('')}</div>`:empty('♧','Your crew belongs here.','Create a private invitation link for each person. They can join using an email or mobile number.','Invite the crew','invite')}</section>${isAdmin()&&live?'<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Pending invitations</h2><button class="text-link" id="load-invites">Show invitations ↗</button></div><div id="invite-list"></div></section>':''}`}
function settings(){const t=state.trip;return intro('MAKE IT YOURS','A trip with your name on it.','Start from scratch. Fill in the details when you know them.')+`<section class="panel settings-card"><div class="panel-head"><h2>Trip essentials</h2>${!isAdmin()?'<span class="row-badge">Admin managed</span>':''}</div><form id="settings-form"><fieldset ${!isAdmin()?'disabled':''} style="border:0;padding:0;margin:0">${field('Trip name','title','text',t.title,true)}${field('Departing from','departure','text',t.departure)}<div class="field-pair">${field('Start date','start','date',t.start)}${field('End date','end','date',t.end)}</div>${field('Total trip budget (INR)','budget','number',t.budget)}${area('The big picture: travel, stay, ideas, or anything the crew should know','notes',t.notes)}${isAdmin()?'<div class="form-actions"><button class="button" type="submit">Save trip details ↗</button></div>':''}</fieldset></form></section><section class="panel settings-card" style="margin-top:20px"><div class="panel-head"><h2>Keep a copy</h2></div><p class="muted">Download the trip as a JSON file before the temporary site is removed.</p><div class="section-actions" style="margin-top:16px"><button class="button outline" data-action="export">↓ Export trip data</button><button class="button outline" data-action="motion">Toggle animations</button></div>${!live?'<p class="note">Personal preview data stays in this browser. It will not automatically transfer to Supabase.</p>':''}</section>${!live?'<section class="panel settings-card" style="margin-top:20px"><div class="panel-head"><h2>A fresh start</h2></div><p class="muted">Clear the trip details saved in this browser.</p><button class="button outline" data-action="reset" style="margin-top:16px">Clear personal preview</button></section>':''}`}
function welcome(){return intro('THE NEXT CHAPTER STARTS HERE','Your people. Your plans. Your Goa.','An invitation-only escape, with everything in one happy place.')+`<section class="hero"><div class="hero-art"><div class="sun"></div><div class="island"></div><div class="wave one"></div><div class="wave two"></div><div class="wave three"></div>${palms}</div><span class="hero-number">01</span><div class="hero-copy"><div class="eyebrow">✦ &nbsp; A LITTLE SUN. A LOT OF STORIES.</div><h2>Good company.<br>Great <em>getaway.</em></h2><p>Our own little corner for a trip we’ll remember. Sign in, bring your ideas, and let’s find our way to the coast.</p><button class="button" data-action="account">${session?'Your account':'Join your crew'} ↗</button></div><div class="hero-caption">MEET ME WHERE THE SEA IS</div></section><section class="panel" style="margin-top:22px">${empty('♧',session?'You’re signed in. Let’s get you in.':'Good times are invitation only.',session?'Reopen your invitation link or ask your trip admin for a new invitation.':'Open your invitation link, enter your email or mobile number, and choose a password. Already joined? Sign in to find your crew.','Open account','account')}</section>`}
function render(){window.dispatchEvent(new CustomEvent('goa-state'));renderNav();$('#identity').innerHTML=`${live?esc(name()):'Your trip space'}<small>${live?(member?esc(member.role):'Sign in to join'):'Personal preview'}</small>`;$('#connection').textContent=live?(member?'Private trip':'Sign in required'):'Personal preview';if(live&&!member){$('#content').innerHTML=welcome();bind();return}const pages={overview,itinerary,discussions,polls,expenses,checklist,links,crew,settings};$('#content').innerHTML=`<div class="page-body">${(pages[currentPage]||overview)()}${!live?'<div class="setup-banner"><span>◌</span><span><strong>Your private design preview.</strong> Changes are saved only in this browser. Group sync, sign-in, and real invitations activate after Supabase setup.</span><a href="#settings">Trip settings ↗</a></div>':''}</div>`;bind()}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeEntry(b.dataset.delete));document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>run(async()=>{const e=state.entries.find(e=>e.id===b.dataset.check);try{await updateEntry(e,{...e.data,done:b.checked})}catch(err){b.checked=!b.checked;throw err}}));document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>run(()=>vote(b.dataset.vote,Number(b.dataset.option))));document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=()=>removeMember(b.dataset.removeMember));document.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>removeFile(b.dataset.removeFile));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadFile(b.dataset.download));if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();const text=e.target.text.value.trim();if(!text)return;run(()=>addEntry('message',{text,author:name()}))};if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();run(async()=>{if(!isAdmin())throw Error('Only the admin can change trip settings.');const t=Object.fromEntries(new FormData(e.target));if(t.start&&t.end&&t.end<t.start)throw Error('The end date must be after the start date.');if(live){await api('saveTrip',{details:t});await sync()}else{state.trip=t;persist();render()}toast('Trip details saved.')})};if($('#load-invites'))$('#load-invites').onclick=()=>run(loadInvites)}
async function vote(id,index){if(!canWrite())return openAccount();const uid=session?.user?.id||'local';if(live){await api('vote',{id,option:index});await sync()}else{state.votes=state.votes.filter(v=>!(v.entry_id===id&&v.user_id===uid));state.votes.push({entry_id:id,user_id:uid,option_index:index});persist();render()}}
function action(a){if(a==='upload')return uploadFile();if(a==='prepare-storage')return run(async()=>{const r=await api('prepareStorage');toast(r.shared_drive?'Trip folders are ready.':'Folders are ready. Uploads require a Shared Drive.');});if(a.startsWith('add-'))return addForm(a.slice(4));if(a==='invite')return invite();if(a==='plan'){location.hash='itinerary';return}if(a==='account')return openAccount();if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify({...state,exported_at:new Date().toISOString()},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='goa-trip-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(a==='motion'){document.body.classList.toggle('motion-off');localStorage.setItem('goa-reduce-motion',document.body.classList.contains('motion-off'));toast(document.body.classList.contains('motion-off')?'Animations paused.':'Animations enabled.');return}if(a==='reset'){openModal('Clear personal preview?',`<p class="modal-note">This deletes the trip data saved in this browser. Export a copy first if you want to keep it.</p><div class="form-actions"><button class="button outline" data-close>Keep my data</button><button class="button danger" id="confirm-remove">Clear preview</button></div>`);$('#confirm-remove').onclick=()=>{state=initial();persist();render();closeModal();toast('A fresh start.')}}}
function invite(){if(!live)return toast('Invitations activate on the connected website.');if(!isAdmin())return toast('Only the trip admin can invite participants.');form('Invite a participant',field('Name or label for this invitation','label','text','',true),async v=>{const {token}=await api('createInvite',{label:v.label});const url=new URL(config.appUrl||location.origin+location.pathname);url.hash='join='+token;setTimeout(()=>{openModal('Your invitation is ready',`<p class="modal-note">Send this private link to ${esc(v.label)}. They can create an account using an email or mobile number and their own password. The link expires in 7 days and works once.</p><input aria-label="Invitation link" id="invite-url" readonly value="${esc(url.href)}"><div class="form-actions"><button class="button" id="copy-invite">Copy link ↗</button></div><p class="note">Anyone holding this unused link can join. Send it directly to the intended person.</p>`);$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Invitation copied.')}catch{$('#invite-url').select();toast('Select and copy the link.')}}},0)},'One private invitation for one crew member. They choose email or mobile when creating their account.')}
async function loadInvites(){const list=await api('listInvites');$('#invite-list').innerHTML=list.length?list.map(i=>`<div class="row"><div class="row-main"><h3>${esc(i.label)}</h3><p>${i.accepted_at?'Joined':i.revoked_at?'Revoked':new Date(i.expires_at)<new Date()?'Expired':'Expires '+new Date(i.expires_at).toLocaleDateString('en-IN')}</p></div>${!i.accepted_at&&!i.revoked_at?`<button class="button small outline" data-revoke="${i.id}">Revoke</button>`:''}</div>`).join(''):'<p class="muted">No invitations yet.</p>';document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>run(async()=>{await api('revokeInvite',{id:b.dataset.revoke});await loadInvites();toast('Invitation revoked.')}))}
function removeMember(id){openModal('Remove this participant?',`<p class="modal-note">Their trip access and existing sessions will be revoked. Contributions remain in the trip.</p><div class="form-actions"><button class="button outline" data-close>Keep participant</button><button class="button danger" id="confirm-remove">Remove access</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{await api('removeMember',{id});await sync();closeModal();toast('Access removed.')})}
function openAccount(){if(!live)return toast('Account creation is available on the connected website.');if(session){openModal('Your account',`<p class="modal-note">Signed in as ${esc(session.user.display_name)} · ${esc(session.user.contact)}</p><div class="form-actions"><button class="button outline" id="signout">Sign out</button></div>`);$('#signout').onclick=()=>run(async()=>{await window.GOA_PWA?.disconnect();await api('logout');saveSession(null);member=null;state=initial();closeModal();render()});return}
 const invited=!!sessionStorage.getItem('goa-invite');
 openModal(invited?'Your Goa story starts here':'Welcome back to the coast',`<p class="modal-note">${invited?'Your invitation lets you create an account. Choose an email address or mobile number as your sign-in ID.':'Sign in with the email address or mobile number you used to join. A new account needs an invitation link.'}</p><form id="auth-form">${invited?field('Your name','display_name'):''}${field('Email or mobile number (with country code)','contact','text',window.GOA_INVITE_INFO?.contact||'',true)}<label for="password">Password</label><input name="password" id="password" type="password" autocomplete="${invited?'new-password':'current-password'}" minlength="10" maxlength="128" required><p class="note">Use at least 10 characters. Mobile example: +91 98765 43210.</p><div class="form-actions">${invited?'<button class="button outline" type="submit" value="login">I have an account</button><button class="button" type="submit" value="register">Create account ↗</button>':'<button class="button" type="submit" value="login">Sign in ↗</button>'}</div></form>`);
 $('#auth-form').onsubmit=e=>{e.preventDefault();const action=e.submitter.value;const data=Object.fromEntries(new FormData(e.target));data.invite=sessionStorage.getItem('goa-invite')||'';run(async()=>{const result=await api(action,data);saveSession(result);sessionStorage.removeItem('goa-invite');await sync();e.target.reset();closeModal();toast('Welcome to your Goa escape.')})}}
async function uploadFile(){if(!canWrite())return openAccount();if(!live)return toast('Uploads are available on the connected website.');openModal('Add a trip file',`<p class="modal-note">Files go into the organised trip folder in Google Drive. Maximum 10 MB per file.</p><form id="upload-form"><label for="upload-category">Save under</label><select name="category" id="upload-category">${storageCategories.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><label for="upload-file">File</label><input id="upload-file" type="file" name="file" required accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.mp4,.mov,.txt,.csv,.json,.docx,.xlsx"><div class="form-actions"><button class="button outline" type="button" data-close>Cancel</button><button class="button" type="submit">Upload to Drive ↗</button></div></form>`);$('#upload-form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=e.target.file.files[0];if(!f||f.size>10485760)throw Error('Choose a file no larger than 10 MB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});const fallback=f.name.endsWith('.heic')?'image/heic':f.name.endsWith('.json')?'application/json':'application/octet-stream';await api('upload',{category:e.target.category.value,name:f.name,mime_type:f.type||fallback,base64});await sync();closeModal();toast('File saved in Google Drive.')})}}
function removeFile(id){const file=state.files.find(f=>f.id===id);if(!file)return;openModal('Move this file to trash?',`<p class="modal-note">“${esc(file.name)}” will be removed from the trip and moved to Google Drive trash. It can be restored in Google Drive. Other files stay in place.</p><div class="form-actions"><button class="button outline" data-close>Keep file</button><button class="button danger" id="confirm-remove">Move to trash</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{await api('deleteFile',{id});await sync();closeModal();toast('File moved to Drive trash.')})}
async function downloadFile(id){try{const r=await fetch(config.supabaseUrl+'/functions/v1/goa-trip-api',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({action:'download',data:{id}})});if(!r.ok)throw Error((await r.json()).error||'Download failed');const blob=await r.blob(),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.files.find(f=>f.id===id)?.name||'trip-file';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
const storageCategories=[['travel/tickets','Travel / Tickets'],['travel/transfers','Travel / Transfers and local transport'],['stay/confirmations','Stay / Confirmations'],['stay/property','Stay / Property details'],['itinerary/plans','Itinerary / Plans'],['itinerary/places','Itinerary / Places and activities'],['expenses/receipts','Expenses / Receipts'],['expenses/shared','Expenses / Shared costs'],['documents/general','Shared documents / General'],['documents/exports','Shared documents / Trip exports'],['memories/photos','Photos and videos / Photos'],['memories/videos','Photos and videos / Videos']];

$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#invite-top').onclick=invite;$('#account').onclick=openAccount;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{if(captureInvite()){currentPage='overview';render();if(session)toast('Sign out to create an account for this invitation.');else openAccount();return}currentPage=location.hash.slice(1)||'overview';$('.sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})});
if(localStorage.getItem('goa-reduce-motion')==='true')document.body.classList.add('motion-off');
function captureInvite(){const hash=location.hash.slice(1);const params=new URLSearchParams(location.search);const token=hash.startsWith('join=')?hash.slice(5):params.get('invite');if(token){sessionStorage.setItem('goa-invite',token);params.delete('invite');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+'#overview');return true}return false}
window.GOA_APP={api,getSession:()=>session,getMember:()=>member,toast,openModal,closeModal};
const hasInvite=captureInvite();
currentPage=location.hash.slice(1)||'overview';
if(live){try{session=JSON.parse(localStorage.getItem('goa-custom-session-v3')||sessionStorage.getItem('goa-custom-session-v2'));if(session&&session.expires_at*1000>Date.now()){saveSession(session);await sync()}else saveSession(null)}catch(e){toast(e.message)}syncTimer=setInterval(()=>{if(!document.hidden&&!$('#modal').open&&!$('#chat-form input:focus')&&!$('#settings-form :focus'))sync().catch(e=>toast(e.message))},15000)}
render();
if(hasInvite&&live&&!session){try{const info=await api('inspectInvite',{invite:sessionStorage.getItem('goa-invite')});if(info.trip_id!==config.tripId)throw Error('This invitation is for a different trip');window.GOA_INVITE_INFO=info;openAccount()}catch(e){sessionStorage.removeItem('goa-invite');toast(e.message)}}
